/**
 * Every line anyone says.
 *
 * Generated by tools/assemble-dialogue.ts from src/data/dialogue.parts/*.json. Edit the JSON, not this
 * file. The brief the writers worked to is docs/BEATS.md.
 *
 * Conventions: node ids are `<npc>-<slot>`. `next` chains without input; `choices` are the only branch
 * points, never more than two. Pip speaks as 'pip': lowercase, few words, a little deadpan, but still plain speech.
 */

import type { DialogueChoice, DialogueNode } from '../core/contracts';

const c = (text: string, next: string, takes?: boolean): DialogueChoice => (takes ? { text, next, takes } : { text, next });
type Opt = { next?: string; choices?: DialogueChoice[]; fill?: string };
const n = (id: string, speaker: string, lines: string[], o: Opt = {}): DialogueNode => ({
  id,
  speaker,
  lines,
  ...o,
});

export const DIALOGUE: Readonly<Record<string, DialogueNode>> = {
  'nana-root': n('nana-root', 'nana', ["Oh, there you are! Come here and let me look at you. That long road's worn you thin.","I'm sorry, love, you've come at a bad time. The radio's gone quiet. The set up at the mast on Brindle Peak has run out of power, and nobody can get through.","Bram, who looks after the woodstore by the big pine, keeps spare batteries. Would you fetch them for me?","And take my old camera with you. Edda, who keeps the set up there, has been wanting one for ages. She'll tell you why."], { choices: [c("i'll go and see bram.", 'nana-errand', true), c("can't the radio wait a bit?", 'nana-chat')] }),
  'nana-chat': n('nana-chat', 'nana', ["Not really, love. The snow's come early this year, and once it settles in, the road closes behind it.","The radio's how we all keep an eye on each other up here. Who's short of flour, whether the lake ice is holding, whose chimney's stopped smoking.","Edda's been sitting up there with a dead set ever since it went. She won't say so, but she'll be lonely.","I'd go up myself, but these knees have done that climb for sixty winters, and they've told me they're finished with it."], { next: 'nana-errand' }),
  'nana-errand': n('nana-errand', 'nana', ["He'll want you to do something for him first. He always does, bless him. Once you've got them, bring the batteries back here to me."]),
  'nana-wait': n('nana-wait', 'nana', ["No batteries yet? Oh, don't worry, there's plenty of day left.","Bram keeps them in his woodstore, over by the big pine.","He's fussy, but he isn't unkind. Whatever he asks you to do, it'll be quick, and he'll be particular about it.","Bring them back here before you head up the hill, mind. There are a few things I'll need to tell you."]),
  'nana-done': n('nana-done', 'nana', ["You got them off him! Heavy, aren't they? That's the radio's voice you're carrying in there.","Here, take my lantern as well. There are lantern posts all the way up the trail, so light them as you go past.","Once they're lit, they'll show you the way back down to me.","Edda keeps the set at the mast. Make sure you give these to her and nobody else."], { choices: [c("what's edda like?", 'nana-edda'), c("i'll head up now.", 'nana-send')] }),
  'nana-edda': n('nana-edda', 'nana', ["Edda's an owl. She's proud, and she's kind, and she can't stand anyone making a fuss of her.","The two of us have talked on that radio every evening for thirty years.","She'll ask you whether I'm keeping well. Tell her yes. And she'll pretend she wasn't worried about me."], { next: 'nana-send' }),
  'nana-send': n('nana-send', 'nana', ["Take the climb slowly. The wind up on the ridge will have the feathers off you if you let it.","And when it's all done, come back down to me. I want to hear all about it from you."]),
  'nana-climb-wait': n('nana-climb-wait', 'nana', ["Still here, love? Edda's waiting up at the mast for those batteries.","Go up through Windscar Ridge and light the posts as you pass. Go on, off you go."]),
  'nana-letter': n('nana-letter', 'nana', ["A letter, for me? From Pell, the postmaster, all the way across the valley?","'The blue house, road head.' Well, that's me. I painted it again in the autumn so there'd be no mistaking it.","Oh. Oh, I'll need to read this one again. And probably again after that.","This is staying by the stove. Next time you're in the hamlet, would you tell Pell it found the right door? He worries."]),
  'nana-home-done': n('nana-home-done', 'nana', ["There you are! I heard you on the radio, love. The whole valley heard you."], { next: 'nana-home-posts' }),
  'nana-home-posts': n('nana-home-posts', 'nana', ["Edda says you did her looking for her. She sounded twenty years younger, I'm telling you.","Now, tell me one thing. Just the one, tonight. I'll get the rest out of you in the morning."], { choices: [c("bram's pile came to four hundred and eighty-one.", 'nana-home-wood'), c("the sky went green over the peak.", 'nana-home-sky')], fill: 'nana-posts' }),
  'nana-home-wood': n('nana-home-wood', 'nana', ["Oh, I know. He told the whole valley on the radio, and then he told them all again.","He'll count it twice tonight, I expect. But it's the first time in years he'll like the answer."], { next: 'nana-home-close' }),
  'nana-home-sky': n('nana-home-sky', 'nana', ["The northern lights? Of course. Edda never could see the green, you know. Now at least she knows it's there.","Was it as bright as they say? No, don't tell me. I'd rather picture it myself."], { next: 'nana-home-close' }),
  'nana-home-close': n('nana-home-close', 'nana', ["But for tonight, come and sit out here with me for a minute. I'd like to look at those posts.","And Pip? I'm glad it was you who went up."], { fill: 'nana-heard' }),
  'nana-idle': n('nana-idle', 'nana', ["Sit down for a minute and get yourself warm. Whatever's out there will keep.","There's always a cup in this house for you. You know where they live.","Off you go whenever you're ready. The valley's still there for you to walk."]),
  'hollis-root': n('hollis-root', 'hollis', ["I've lost a mitten. The left one, and it was the good one, too.","And I know who took it. Fen, the owl who sits watching from the pines.","Go and ask him what he's got to say for himself."], { choices: [c("i'll go and ask fen.", 'hollis-wait', true), c("why would an owl take a mitten?", 'hollis-chat')], fill: 'hollis-hello' }),
  'hollis-chat': n('hollis-chat', 'hollis', ["He's an owl, isn't he? He sits up there and watches everybody with those great big eyes.","And he never says a word to anyone. Looks guilty to me."], { next: 'hollis-wait' }),
  'hollis-wait': n('hollis-wait', 'hollis', ["Fen won't tell you a thing unless you ask him, so ask him straight out.","And while you're over there, try dropping a line in the creek pool below the split pine. Just in case he dropped it in when he flew off.","Then come back and tell me what he said."]),
  'hollis-done': n('hollis-done', 'hollis', ["You fished it out of the creek? Under the split pine?","So it wasn't Fen after all. It was the wind. Well, I never.","I suppose I'll have to say something to him. One of these days.","Here, have my spare. One mitten's no use to me on its own. And don't argue, I don't like owing anybody."]),
  'hollis-idle': n('hollis-idle', 'hollis', ["The wind's picking up. Keep yourself wrapped up warm, Nana's girl."], { fill: 'hollis-idle' }),
  'hollis-fit': n('hollis-fit', 'hollis', ["A headband? From Tamsin, the marten up in the pines? For me?","...It's a bit tight round the ears. But it stays on, and it's warm. Don't you go telling anyone I said it was warm.","Tell her it fits. And tell her she could've just asked me, you know."]),
  'bram-batteries': n('bram-batteries', 'bram', ["Four hundred and... no, hang on, that one's sticking out. I'll have to start again.","Batteries? Nana sent you, did she? They're in the woodstore, behind that heap there.","The end of my pile came down, you see. Without an end the rows all lean, and I can't count a leaning row. Put it back up for me and they're yours."], { choices: [c("why does it need to be straight?", 'bram-why'), c("all right. i'll stack it.", 'bram-how')] }),
  'bram-why': n('bram-why', 'bram', ["When a pile's straight, you just count the rows. When it's crooked, you have to count every single log. I've counted it three times today and got three different numbers.","And I can't go into winter with three numbers. I need the one."], { next: 'bram-how' }),
  'bram-how': n('bram-how', 'bram', ["It wants eight logs on the end, laid square across each other. And I'll know if you've cheated, because I'll count them."]),
  'bram-stack': n('bram-stack', 'bram', ["That's still a heap. I can see it from here, you know.","Eight logs, square across each other. Then come and tell me it's done."]),
  'bram-paid': n('bram-paid', 'bram', ["Right, let me count. Four hundred and seventy-three in the rows, and eight on the end. They're yours.","Four hundred and eighty-one. The same number twice in a row. Do you know how long it's been since that happened?","Here you are, the spare batteries. Do be careful with them, they're the only ones in the valley."], { next: 'bram-rope' }),
  'bram-rope': n('bram-rope', 'bram', ["And since you're going up there anyway: the bridge rope on Windscar Ridge is wearing through. Everyone knows it.","Tuck, the marten who looks after that bridge, hasn't spoken to me in years. He'd never come down here and ask.","So take him my good rope. Forty feet of it, coiled, no splices. I checked it myself.","And tell Tuck I want it back the same length. I'll be measuring it."]),
  'bram-rope-wait': n('bram-rope-wait', 'bram', ["Tuck's up at the bridge on Windscar Ridge. Forty feet, mind. I'll know if it comes back short."]),
  'bram-rope-done': n('bram-rope-done', 'bram', ["It's tied on? He took it? From me?","'Still forty feet,' he says. 'Come up and measure it yourself,' he says. Well.","And what's that you've got there, with the bent bow? Give it here. That's the key to my woodshed.","I trod on it and bent it the winter we stopped talking. And he's kept it tied in his rope all this time.","Well. Come the spring, I'll walk up there with my tape measure. Somebody has to check it."]),
  'bram-idle': n('bram-idle', 'bram', ["Four hundred and seventy-nine, eighty, eighty-one. Right, from the top. Don't talk to me, I'm counting.","Wood's the one thing in this valley that stays counted. I like that about it.","People don't, mind. People keep changing their numbers on you.","Go on, then. Watch the pile on your way past."]),
  'edda-early': n('edda-early', 'edda', ["A visitor, all the way up here? You've climbed a long way to look at a dead radio.","I keep the radio set here at the mast. The whole valley talks to each other through it.","Well, they did. It's run out of power, and I'm waiting on batteries from down below.","Nana Quill, down at the cabin, is seeing to it. If you see her, tell her I'm still up here."]),
  'edda-meet': n('edda-meet', 'edda', ["You'll be Nana's Pip. I'd know that lantern anywhere. And those must be my batteries.","There, can you hear it humming? The set's warming up. But it can only reach the valley when the aurora's out.","And how is Nana keeping? Is she well?"], { choices: [c("she's keeping well.", 'edda-nana-well'), c("she said you'd ask that.", 'edda-nana-caught')] }),
  'edda-nana-well': n('edda-nana-well', 'edda', ["Good. Not that I was worried, mind you. I only asked to be polite.","Thirty years we've talked every evening, and these have been the quietest nights I've had up here."], { next: 'edda-ask' }),
  'edda-nana-caught': n('edda-nana-caught', 'edda', ["Did she, now? And I suppose she told you I'd pretend I wasn't worried.","Well, I was, a little. I haven't heard her voice since the set went dead. Don't you go telling her that."], { next: 'edda-ask' }),
  'edda-ask': n('edda-ask', 'edda', ["Now, here's my trouble. I'm an owl, and I see the night in greys.","Three nights now I've called out on a cloud I thought was bright, and nobody down in the valley heard a thing.","Nana's camera can see green. I can't.","So if you can catch the aurora in a photograph, come and tell me the moment it's up."], { choices: [c("where should i look?", 'edda-look'), c("what if it doesn't come?", 'edda-ifnot')] }),
  'edda-look': n('edda-look', 'edda', ["Look north, over the shoulder of the peak. It starts off low, like a stain on the sky. Give it time to climb.","Then come straight to me. It doesn't stay out for long."]),
  'edda-ifnot': n('edda-ifnot', 'edda', ["Then we'll wait another night. But the snow's on its way, and when it comes, the road shuts.","Look north, over the shoulder of the peak. And come straight to me when you see it."]),
  'edda-wait': n('edda-wait', 'edda', ["The set's warm and I've got my talon on the dial. The rest is up to the sky.","Look north, over the shoulder of the peak. It's green, low down at first, and then it climbs. Get it on the camera, then come and tell me."]),
  'edda-line-up': n('edda-line-up', 'edda', ["It's up? Then here we go. Come and stand by me.","Brindle Peak calling the valley. Brindle Peak calling. Is anyone there? Over.","Nothing yet, only static. The sky has to find us first. Give it a moment...","There!"], { next: 'edda-line-bram' }),
  'edda-line-bram': n('edda-line-bram', 'bram', ["Hearth Hollow here, by the big pine. The woodstore's full. Four hundred and eighty-one logs. Over."], { next: 'edda-line-orla' }),
  'edda-line-orla': n('edda-line-orla', 'orla', ["Come up and have some, any of you. Over."], { next: 'edda-line-skiff', fill: 'orla-radio' }),
  'edda-line-skiff': n('edda-line-skiff', 'skiff', ["The boathouse on the Frozen Reach here. The ice is holding, and the lake's nice and quiet. Over."], { next: 'edda-line-ivy' }),
  'edda-line-ivy': n('edda-line-ivy', 'ivy', ["Anyone who's cold, come on down. Over."], { next: 'edda-line-wren', fill: 'ivy-radio' }),
  'edda-line-wren': n('edda-line-wren', 'wren', ["It's Wren, in Pinewind Wood. The mast's humming again, I can hear it from here. Over."], { next: 'edda-line-gus' }),
  'edda-line-gus': n('edda-line-gus', 'gus', ["It's Gus, at the bell shop in the hamlet! I'm holding the big bell's rope right now!","Next time you call, I'm going to ring it. I really am. Over."], { next: 'edda-line-pass' }),
  'edda-line-pass': n('edda-line-pass', 'edda', ["Can you hear that, faint, under the others? That's the road crew, down below the pass.","They're bringing the plough up in the morning. The road's staying open."], { next: 'edda-line-nana' }),
  'edda-line-nana': n('edda-line-nana', 'nana', ["Edda, is that you? Is Pip up there with you?","Oh, good. Oh, that's good. No, don't tell me anything, I want to hear it from her.","And everyone along the trail, if there's a post near you, light it. She'll be coming down in the dark."], { next: 'edda-line-end' }),
  'edda-line-end': n('edda-line-end', 'edda', ["That's the whole valley, and the line's holding.","Thirty winters I've kept this set, and I've never heard it so crowded.","Go on home now, Pip. Follow the lights down.","I'll look after the set. Brindle Peak, over and out."], { fill: 'radio-unmet' }),
  'edda-idle': n('edda-idle', 'edda', ["The line's held ever since. They've hardly stopped talking.","Bram, down by the big pine, has read me his count four times now.","Give Nana my love, would you? She'll pretend she doesn't need it.","Watch yourself on the ridge going down. The wind's in a mood tonight."]),
  'wren-root': n('wren-root', 'wren', ["You must be Nana's Pip. She said you'd be coming up the valley before the snow.","I'm Wren. I write down what the valley sounds like: the springs, the ice, the pines knocking together.","My book's nearly full now. There's one page left, and I can't think of anything worth putting on it."], { choices: [c("what's wrong with the page?", 'wren-chat'), c("what would be worth writing?", 'wren-errand')] }),
  'wren-chat': n('wren-chat', 'wren', ["Oh, it's not the page, it's me. Everything I hear sounds like something I've already written down.","The very first page I ever wrote was the mast on Brindle Peak, humming in the cold. I was younger than you are."], { next: 'wren-errand' }),
  'wren-errand': n('wren-errand', 'wren', ["So would you listen for me? You've got fresh ears. Go to the hoarfrost glade and take a photograph there.","Holding still for a picture is about the only time anybody really listens. You'll hear the frost.","Then go down to Kettle Springs and walk in among the hot pools. Nothing else sounds like that water, and you'll hear it as you go.","Then come back and tell me what you heard, and I'll put it on the last page."], { fill: 'wren-hum' }),
  'wren-wait': n('wren-wait', 'wren', ["Oh, you're back. Go to the hoarfrost glade first, and hold still for the picture so you can listen.","Then walk in among the hot pools at Kettle Springs and listen there too. Then come and tell me."]),
  'wren-still': n('wren-still', 'wren', ["Go to the glade first, for the frost. Then the hot pools at Kettle Springs. And then come back to me."]),
  'wren-done': n('wren-done', 'wren', ["You've been to both? Go on, then, tell me. What did you hear?"], { choices: [c("the frost ticked, like a stove cooling down.", 'wren-frost'), c("the springs sounded like a kettle arguing with itself.", 'wren-kettle')] }),
  'wren-frost': n('wren-frost', 'wren', ["Like a stove cooling down. Oh, that's exactly it. I'd stopped being able to hear it.","And the springs? No, keep that one to yourself. I'll go down and hear it for myself."], { next: 'wren-write' }),
  'wren-kettle': n('wren-kettle', 'wren', ["A kettle arguing with itself. Oh, that's exactly it. I'd stopped being able to hear it.","And the frost? No, keep that one to yourself. I'll go up to the glade and listen for myself."], { next: 'wren-write' }),
  'wren-write': n('wren-write', 'wren', ["There. That's the last page, and the book's full.","You take it. I'll start a new one tomorrow, with my ears washed out."]),
  'tamsin-root': n('tamsin-root', 'tamsin', ["Oh! Mind the needles, they get everywhere. I'm Tamsin. I knit things.","This is a headband for the hare down by the road head. His ears go flat in the cold, poor thing.","Only I've never measured him. I didn't like to ask. So it might not fit him at all."], { choices: [c("why not just ask him?", 'tamsin-chat'), c("how will you know if it fits?", 'tamsin-errand')] }),
  'tamsin-chat': n('tamsin-chat', 'tamsin', ["Walk up to a hare and ask him to hold still while I measure his ears? I'd rather knit in the dark.","So I guess. I always guess. Would you help me find out whether I guessed right?"], { next: 'tamsin-errand' }),
  'tamsin-errand': n('tamsin-errand', 'tamsin', ["He lives down by the road head, in Hearth Hollow. Hollis, he's called.","Would you take it to him and ask him to try it on? I'd only fret if I went myself.","And have a go at the pinecone toss while you're here, if you like. I do enjoy watching someone else be bad at something.","Then come back and tell me if it fits. Honestly, mind. I'd rather know."]),
  'tamsin-wait': n('tamsin-wait', 'tamsin', ["Still got it with you? It's for Hollis, the hare by the road head. Ask him to try it on.","And if it's too tight, you tell me. I'd rather know."]),
  'tamsin-done': n('tamsin-done', 'tamsin', ["It fits? A bit tight on the ears, but it fits? Oh, thank goodness for that.","Then I'll give the next one more room round the ears. You keep this one. It was practice.","And next time, I'll ask him myself. Out loud and everything."]),
  'fen-root': n('fen-root', 'fen', ["You're up early. Or late. It's hard to tell from up a pine.","I keep watch over the pines. Everything that moves through here goes down in my tally. Well, nearly everything."], { choices: [c("what's missing?", 'fen-errand'), c("why keep a tally?", 'fen-chat')] }),
  'fen-chat': n('fen-chat', 'fen', ["The wood's full of comings and goings, and somebody ought to keep track of them. It isn't prying if you write it down.","Most folk talk around an owl and hope he'll fill in the rest. I don't, as it happens."], { next: 'fen-errand' }),
  'fen-errand': n('fen-errand', 'fen', ["From this branch I can see the creek. Up the hill there's a deer trail, but the trees hide it from me.","Something comes down that trail every day. I see it go in at the top, but I never see what it is.","If you run the trail, fast, you'll see where it bends, past the glade and the split pine.","Tamsin, the marten who knits by the split pine, sits right at the bend. Ask her what comes past."]),
  // True before the run and after it: critic round 80 had run the trail and was still told to run it first.
  'fen-wait': n('fen-wait', 'fen', ["You're back. Have you asked Tamsin yet? She sits by the split pine, right where the deer trail bends.","Run the trail fast first, if you haven't yet, and ask her what comes down it. Then come and tell me."]),
  'fen-still': n('fen-still', 'fen', ["Ask Tamsin, by the split pine, what comes down the deer trail. Run the trail fast first, if you haven't yet."]),
  'fen-done': n('fen-done', 'fen', ["A roe deer? Coming down from the glade to drink at the creek, every morning?","There. That's the last line in my tally.","Twenty winters I've watched this wood, and I could have asked the marten next door any day I liked."]),
  'ilsa-root': n('ilsa-root', 'ilsa', ["You're Pip, aren't you? Nana's told me all about you. Don't stand still too long, you'll freeze.","I'm Ilsa. I carry things for people. Firewood, parcels, whatever needs carrying.","This one's for my sister. Only we had words, and I'd rather not be the one to take it over."], { choices: [c("what did you have words about?", 'ilsa-chat'), c("where am i taking it?", 'ilsa-errand')] }),
  'ilsa-chat': n('ilsa-chat', 'ilsa', ["She says I carry everybody else's load and then sulk because nobody carries mine.","And I say she sits in her steam and waits for everyone to come to her.","We're both right, which is the worst way to have a row."], { next: 'ilsa-errand' }),
  'ilsa-errand': n('ilsa-errand', 'ilsa', ["My sister Ivy keeps the hot pools at Kettle Springs, down the valley.","Put it in her hands, would you, not on the step. She'll say I should have come myself.","Don't argue with her about it. Just come back and tell me it got there."]),
  'ilsa-wait': n('ilsa-wait', 'ilsa', ["Still carrying it? That's all right. Ivy, my sister, is down at the pools, in the steam.","If she starts on about me, don't argue. Just hand it over and tell her it's from me."]),
  'ilsa-done': n('ilsa-done', 'ilsa', ["It got there? She took it?","And she said I should come down myself. Of course she did.","Well, then. Tomorrow I'll go down there, carrying nothing at all, and let her feed me.","But sit down for a minute first. No, really, sit. I'm practising."]),
  'fen-mitten': n('fen-mitten', 'fen', ["You asked me straight out. Hardly anybody does that. Most folk drop hints and hope.","I did see it. Hollis, the hare, hung it on a low branch to dry.","The wind took it into the creek pool below the split pine. That's the pine with two tops, standing over the rest, a short walk up the creek from my branch. Fish there and you'll hook it.","I never took it. Tell him that from me. He's been thinking it for two days."]),
  'tamsin-trail': n('tamsin-trail', 'tamsin', ["Fen, the owl, wants to know what comes down the deer trail? He could have just asked me.","It's the roe deer from the hoarfrost glade. She comes past my stump every morning on her way down to the creek for a drink.","Tell him that. And tell him he's allowed to come and ask me himself, you know."]),
  'wren-idle': n('wren-idle', 'wren', ["I've started a new book. I write more slowly now, and I listen for longer first.","Listen, can you hear that knocking? That's the pines in the cold. I'd stopped noticing it.","If you hear anything I haven't, come and tell me, and I'll write it down."]),
  'tamsin-idle': n('tamsin-idle', 'tamsin', ["I'm knitting him another one. Measured, this time. I asked the hare to hold still, and he did.","It turns out people quite like being asked. Who knew?","Mind the needles on the stump. They're sharper than they look."], { fill: 'tamsin-idle' }),
  'fen-idle': n('fen-idle', 'fen', ["My tally's complete now. A roe deer, every morning, down to the creek.","I asked the marten by the split pine a question yesterday. She talked for an hour. I might do it again.","Ask me something, if you like. I always answer when I'm asked."]),
  'ilsa-idle': n('ilsa-idle', 'ilsa', ["I'm going down to see Ivy, my sister, tomorrow. I'm going to let her feed me.","Don't tell her, though. She'll make a big fuss about it, and I'll secretly enjoy every minute.","Sit with me a while. I'm practising sitting still. I'm not very good at it yet."]),
  'skiff-root': n('skiff-root', 'skiff', ["You're the bird from up the valley, aren't you? Nana's girl.","Look at all this. Three feet of ice, and not a drop of water to float a boat on.","I've got a sled up in the rafters. It's been up there since the lake froze, and nobody ever rides it."], { choices: [c("i'll ride it.", 'skiff-errand', true), c("what's a captain without water?", 'skiff-chat')] }),
  'skiff-chat': n('skiff-chat', 'skiff', ["An otter with a boat stuck in a field, that's what.","The pike are down there somewhere, sitting in the dark and laughing at me.","I know where they sit, mind you. Ask me later if you ever want to find them."], { next: 'skiff-errand' }),
  'skiff-errand': n('skiff-errand', 'skiff', ["Then go and find Margit, the raven who measures the ice. She's out there now.","Ask her whether it'll hold a sled. And don't let her talk your ear off."], { next: 'skiff-pip', fill: 'skiff-hill' }),
  'skiff-pip': n('skiff-pip', 'pip', ["so, a sled that nobody rides...","and a raven who measures the ice. got it."]),
  'skiff-wait': n('skiff-wait', 'skiff', ["Ask the raven, Margit, whether the ice will hold. She's very precise about it.","Then come back and tell me what she says."], { fill: 'skiff-wait-hill' }),
  'skiff-still': n('skiff-still', 'skiff', ["Then go and ask the raven, Margit, whether the ice will hold a sled."], { fill: 'skiff-still-hill' }),
  'skiff-done': n('skiff-done', 'skiff', ["So the raven says it'll hold? That's good enough for me.","Then mine's coming down off the roof. Here you are. It's not a loan, it's yours, on any slope you like.","Ride it hard. That's all a sled wants, same as a boat."]),
  'skiff-pike': n('skiff-pike', 'skiff', ["Margit, the raven, wants to know where my pike are? She sent you to ask me, did she?","Oh, fine. Off the end of the old jetty, where the bottom drops away.","They sit there all winter long, in the dark. Don't you go telling anybody else.","And tell her I said to write it down properly."]),
  'skiff-flour': n('skiff-flour', 'skiff', ["Flour for Orla, up at the bakery? Aye, it's in the hold.","The boat's frozen in, but the hold's dry enough. Three sacks, all sealed up in oilcloth.","I'll haul them up the hill on the sled this evening. You can tell her that.","And tell her I'll be wanting the first loaf. That's the captain's due."]),
  'skiff-idle': n('skiff-idle', 'skiff', ["Still no water, and I'm still a captain. Somebody has to be.","Do ride that sled for me. It's been waiting even longer than I have.","Come the spring, I'll take you out on real water. You'll see."]),
  'margit-root': n('margit-root', 'margit', ["The ice is forty-one centimetres thick at the centre, and forty-three at the edge.","Skiff, the otter with the boat, calls that luck. I call it a measurement.","I'm counting today. You could fish, if you like, and bring me something worth writing down."], { choices: [c("i'll fish.", 'margit-errand', true), c("why measure the ice?", 'margit-chat')] }),
  'margit-chat': n('margit-chat', 'margit', ["Because the lake doesn't lie. People do, now and then, but numbers never do.","Skiff seems to think the ice froze just to insult him. I think it's a record.","Go on, the hole's already drilled. I'll count while you pull."], { next: 'margit-errand' }),
  'margit-errand': n('margit-errand', 'margit', ["Fish the hole, and I'll count the minutes. Whatever bites, I'll write it down.","Then ask Skiff, the otter with the boat, where the pike sit.","He knows perfectly well. He just won't say it out loud, not to me."]),
  'margit-wait': n('margit-wait', 'margit', ["You're back. The hole's still open, and I'm still counting.","Fish it first, then get Skiff to tell you where the pike sit."]),
  'margit-still': n('margit-still', 'margit', ["Fish the hole while I count. Then ask Skiff, the otter, where the pike sit."]),
  'margit-done': n('margit-done', 'margit', ["Here's the good bait for you. Use it off the jetty, and bring me back the next number."], { fill: 'margit-catch' }),
  'margit-sled': n('margit-sled', 'margit', ["Skiff, the otter with the boat, wants to know if the ice will hold a sled?","It's forty-one centimetres at the centre. It would hold Skiff and his boat both.","Tell him yes. And tell him it's a measurement, not luck.","And tell him to stop sulking at the lake. It doesn't notice."]),
  'margit-idle': n('margit-idle', 'margit', ["It's forty-one at the centre and forty-three at the edge, same as yesterday.","Same is good, you know. It means the record's holding.","Fish if you like, and I'll count. I always count."]),
  'orla-root': n('orla-root', 'orla', ["You must be Pip. Come and sit down, you look frozen through.","The oven's on, but I've run out of flour. Skiff, the otter with the boat, has got it.","Would you go and ask him for me?"], { choices: [c("i'll ask skiff.", 'orla-errand', true), c("why is the flour on a boat?", 'orla-chat')] }),
  'orla-chat': n('orla-chat', 'orla', ["Skiff brings it up the lake for me every autumn. This year the ice beat him to it.","So the sacks are sitting in his hold, frozen in, and my oven's just burning wood.","He'll know if any of it's still dry. Ask him nicely, mind. He's touchy about that boat."], { next: 'orla-errand' }),
  'orla-errand': n('orla-errand', 'orla', ["Skiff's boat is iced in down on the Frozen Reach. He'll know what's on board."], { next: 'orla-pip', fill: 'orla-green' }),
  'orla-pip': n('orla-pip', 'pip', ["flour stuck in a frozen boat. poor oven."], { fill: 'orla-pip-green' }),
  'orla-wait': n('orla-wait', 'orla', ["No flour yet? I expect Skiff's been telling you about the one that got away.","Take your time, love. The oven'll keep."], { fill: 'orla-snowman' }),
  'orla-done': n('orla-done', 'orla', ["The flour's coming? Tonight? Oh, then the oven can stay on.","And there's a snowman out on the green, leaning on my window. That's yours, I'd bet. It's just right.","Here, take two tins of soup. One's for you, and one's for Nana.","And Skiff wants the first loaf, does he? He'll get it. Thank you, love."]),
  'orla-news': n('orla-news', 'orla', ["Corm, the raven, is telling people we're closed? I've been open since five this morning.","Flour or no flour, the oven's lit, and as far as I'm concerned that means we're open.","Tell him to come in and eat something. And then tell him to check his facts."]),
  'orla-blue': n('orla-blue', 'orla', ["Which house is blue? Mine is. Look at the door, I painted it in the spring.","Pell asks me that every single winter. And then he goes and asks somebody else.","Tell him it's the bakery. Blue door, flour on the step. He can't miss it."]),
  'orla-b': n('orla-b', 'orla', ["I've lit the market lamps for a night bake. Four loaves won't feed a queue like this.","I'd love a picture of the lamps for the window. And somebody to ring a bell when the bread comes out.","Gus, who sells bells across the square, has the loudest one. Could you borrow him for an hour?"], { choices: [c("i'll photograph the lamps.", 'orla-berrand', true), c("why gus?", 'orla-bchat')] }),
  'orla-bchat': n('orla-bchat', 'orla', ["He's loud. Folk hear that bell and know the bread's out.","He'll talk your ear off, mind, but he'll do it."], { next: 'orla-berrand' }),
  'orla-berrand': n('orla-berrand', 'orla', ["Then go and fetch Gus from his shop, and bring his bell.","Then come back and tell me the queue's been fed."], { fill: 'orla-lamps' }),
  'orla-bwait': n('orla-bwait', 'orla', ["Then go and fetch Gus from the bell shop, and his bell with him."], { fill: 'orla-lamps-wait' }),
  'orla-bstill': n('orla-bstill', 'orla', ["And then you'll need to fetch Gus from the bell shop, with his loud bell."], { fill: 'orla-lamps-still' }),
  'orla-bdone': n('orla-bdone', 'orla', ["Nine loaves! The whole queue's been fed.","You can take the credit. I'm going to sit down for five minutes.","Thank you, Pip. I mean it."]),
  'orla-idle': n('orla-idle', 'orla', ["Nine loaves one day, four the next. The right number's somewhere in between.","Sit yourself down, Pip, you look frozen through. There's always a heel of bread for you here.","And tell Nana there's a loaf here for her whenever she wants one."], { fill: 'orla-bell' }),
  'pell-root': n('pell-root', 'pell', ["I've got one letter left in my bag, and it's been sitting in there for a week.","It just says 'The blue house, road head.' But I've got four blue houses on my round.","I even numbered them. It didn't help."], { choices: [c("i'll take the letter.", 'pell-errand', true), c("why are there four blue houses?", 'pell-chat')] }),
  'pell-chat': n('pell-chat', 'pell', ["The paint fades up here. The frost takes the blue first, and then it all goes grey.","So I've got four doors that were blue once, and only the one letter.","Nana's cabin at the road head is my best guess. Would you take it and ask her?"], { next: 'pell-errand' }),
  'pell-errand': n('pell-errand', 'pell', ["Take the letter down to Hearth Hollow and give it to Nana at the cabin.","Into her hands, mind, not on the step. Then I'll be able to sleep."], { next: 'pell-pip' }),
  'pell-pip': n('pell-pip', 'pip', ["a blue door at the road head...","nana's door is blue."]),
  'pell-wait': n('pell-wait', 'pell', ["Still got it? Nana's cabin is in Hearth Hollow, up at the road head.","Put it into her hands. That's all I ask."]),
  'pell-done': n('pell-done', 'pell', ["You gave it to Nana? And it was the right house?","One letter, delivered to the right door. I'll take that.","And she's keeping it by her stove? That's where the good letters go. That's a job done properly."], { next: 'pell-b' }),
  'pell-bell': n('pell-bell', 'pell', ["Gus, the bell-seller, wants to know how far his shop bell carries?","I heard it ring from the far end of my round. Nice and clean, it was.","It carries right across the hamlet. Every door I knocked on, the sound had got there before me.","Tell him the whole hamlet. He'll go all pink. Let him."]),
  'pell-news': n('pell-news', 'pell', ["Is the post running? Corm, the raven, sent you to ask me? Typical.","Inside the valley, yes, it is. I walk it every morning, door to door.","Over the pass, no. Nothing goes over until the road's been cleared.","Tell him both halves, mind. He only ever passes on one of them."]),
  'pell-b': n('pell-b', 'pell', ["That letter found Nana by luck. The next one might not.","Orla, the mouse with the bakery, knows every door in the hamlet. Would you ask her which house is blue?","And Ivy, the otter who looks after the springs, can see the whole hill from down there. Ask her as well."], { choices: [c("i'll ask orla.", 'pell-berrand', true), c("why ivy?", 'pell-bchat')] }),
  'pell-bchat': n('pell-bchat', 'pell', ["From the pools, Ivy can see every house on the hill. That's her post, in a way.","And Orla sees every door from behind her counter. Between the two of them, they've got my whole round."], { next: 'pell-berrand' }),
  'pell-berrand': n('pell-berrand', 'pell', ["So ask Orla which house is blue, and ask Ivy, down at the springs, as well.","Then come back to me. I'll have the ledger open."]),
  'pell-bwait': n('pell-bwait', 'pell', ["You're back. I've got the ledger open. So, which house is blue?","Ask Orla at the bakery first, and then Ivy, down at Kettle Springs."]),
  'pell-bstill': n('pell-bstill', 'pell', ["Ask Orla, at the bakery, which house is blue, and then Ivy, at the springs. I'll keep the ledger open."]),
  'pell-bdone': n('pell-bdone', 'pell', ["Orla says it's her door. Ivy says it's the green one, from where she sits.","So that's two answers, and they're both right from where they're standing. Which is no use at all to a postman.","So I'll stop writing colours on the letters and write names instead. Everyone knows a name.","Thank you, Pip. I'll be able to sleep now."]),
  'pell-idle': n('pell-idle', 'pell', ["I write names on the front now, not colours. Not a single letter's gone astray since.","It turns out everybody knows where everybody else lives. I only had to ask.","Mind the step. I've sanded it, but it still catches people out."]),
  'gus-root': n('gus-root', 'gus', ["I sell bells, every size there is. And I've never once heard the big one ring.","My shop bell, though. One clean strike, and I'd love to know how far it goes.","Pell, the postmaster, walks the whole hamlet. Would you ask him if he heard it?"], { choices: [c("i'll find out.", 'gus-errand', true), c("why not ring the big bell?", 'gus-chat')], fill: 'gus-hello' }),
  'gus-chat': n('gus-chat', 'gus', ["It's the biggest bell in the valley! Nobody's rung it in years.","What if I pull the rope and it just goes clunk? In front of everybody?","So I'll try the shop bell first. If that one carries, maybe the big one will too."], { next: 'gus-errand' }),
  'gus-errand': n('gus-errand', 'gus', ["Then ask Pell how far the sound travelled. He'll know, he hears every door."], { fill: 'gus-ring' }),
  'gus-wait': n('gus-wait', 'gus', ["And then Pell, out on his round, can tell you how far it carried."], { fill: 'gus-ring-wait' }),
  'gus-still': n('gus-still', 'gus', ["And then Pell, the postmaster, can tell you how far it carried."], { fill: 'gus-ring-still' }),
  'gus-done': n('gus-done', 'gus', ["It carries across the hamlet? The whole hamlet?","Then the big bell could reach the whole valley! I'll have to try it. Soon. Well, fairly soon.","Here, take these bells for your trouble. You can spend them on my feathers. They'll give you more breath for flying."]),
  'gus-bake': n('gus-bake', 'gus', ["Orla, at the bakery, wants me? For a whole hour? To ring?","I'd ring for bread any day. The loaves come out, the bell rings, and the queue comes running.","Lock up the shop? No, nobody steals bells. They'd be heard.","Tell her I'm on my way, and I'm bringing the loud one."]),
  'gus-idle': n('gus-idle', 'gus', ["Bells! Bells for sale! ...Oh, it's you. Hello again.","I'm working my way up to the big bell. I've held the rope, which is a start.","One day I'll pull it, and the whole valley will hear. You'll see.","Those two feathers by my feet are forty bells each. They'll give you longer breath for the climb."]),
  'ivy-root': n('ivy-root', 'ivy', ["Careful, don't splash. I'm Ivy. I look after the pools, and the pools are going cold.","They're two degrees down since the first snow. Everyone keeps telling me it's the weather.","But it isn't. It's the stone dam on the low pool. Somebody's been knocking stones out of it."], { choices: [c("who'd knock stones out?", 'ivy-chat'), c("what can i do?", 'ivy-errand')] }),
  'ivy-chat': n('ivy-chat', 'ivy', ["Whoever comes off the otter slide too fast. I'm not naming any names.","Everyone who slides into the dam knocks a stone loose, and the warm water runs out through the gap.","I've kept these pools for eleven winters, and I'm not losing them to somebody's bit of fun."], { next: 'ivy-errand' }),
  'ivy-errand': n('ivy-errand', 'ivy', ["Then get the temperature off Corm, the raven who sits by the steam. The thermometer's on his rock.","He's sat right next to it for a whole year and never once read it. Make him read it.","I want a proper number, mind, not news."], { fill: 'ivy-dam' }),
  'ivy-wait': n('ivy-wait', 'ivy', ["And then Corm, on his rock by the steam. Make him read the thermometer.","I want a number, mind, not something he's heard."], { fill: 'ivy-dam-wait' }),
  'ivy-done': n('ivy-done', 'ivy', ["Forty-one? Off the thermometer? Corm actually read it?","That's up on last week. The dam's holding. Listen to that steam.","Here, have a warm stone from the bottom of the pool. Keep it in a pocket.","And if you see my sister, don't tell her I was worried."]),
  'ivy-bundle': n('ivy-bundle', 'ivy', ["This is from Ilsa, my sister? She sent it with you instead of coming herself.","And don't tell me we don't look alike. Everyone says that.","She'd carry the whole valley on her back before she'd knock on my door. Dried apples, and her good scarf.","Tell her it got here. And tell her to come down herself next time, and I'll feed her."]),
  'ivy-blue': n('ivy-blue', 'ivy', ["Which house is blue? From down here, it's the one with the green door.","At dusk the steam turns everything up the hill blue, and that one most of all.","Pell, the postmaster, ought to come down and look for himself. He never comes down here."]),
  'ivy-idle': n('ivy-idle', 'ivy', ["Soak your feet before you go. Everybody's feet are cold this time of year."], { fill: 'ivy-idle' }),
  'corm-root': n('corm-root', 'corm', ["News! You'll be wanting the news. I'm Corm. I hear everything, and I pass it all on.","Word is the bakery in Hollowpine Hamlet is shut. Mind you, word is it's open, too.","And word is the post's stopped. Also that it's running. I've been saying all four since breakfast."], { choices: [c("which one's true?", 'corm-chat'), c("have you checked?", 'corm-check')] }),
  'corm-chat': n('corm-chat', 'corm', ["No idea! That's the trouble. I say what I hear, and I hear everything.","Just once, I'd like to say something and have it be true."], { next: 'corm-errand' }),
  'corm-check': n('corm-check', 'corm', ["Checked? I'd have to go and ask people. They look at you funny when you ask.","Hearing's easier. Things you hear come to you."], { next: 'corm-errand' }),
  'corm-errand': n('corm-errand', 'corm', ["Orla, who runs the bakery, would know whether it's open.","And Pell, the postmaster, would know whether the post's running.","Would you ask them for me? Then come back and tell me straight, and I'll pass it on right, for once."]),
  'corm-wait': n('corm-wait', 'corm', ["You're back! With news? No? Orla first, at the bakery. Is it open?","Then Pell, the postmaster. Is the post running?","Then come back to me and tell me slowly. I want to get it right."]),
  'corm-still': n('corm-still', 'corm', ["Ask Orla, at the bakery, whether it's open, and Pell, the postmaster, whether the post's running. Then come back to me."]),
  'corm-done': n('corm-done', 'corm', ["The bakery's open. The post runs inside the valley, but nothing goes over the pass.","And it's all true? Checked? By somebody who actually asked?","Well! I'll pass that on, every word of it. I could get used to this.","Here, for your trouble. And that's not hearsay, those are real bells."]),
  'corm-temp': n('corm-temp', 'corm', ["The pool temperature? I heard it was freezing. Jory, the mouse, told me so.","Ivy wants a reading? Off the thermometer? Not just what I heard?","Oh, fine. The thermometer's right here. I've never once read it. ...Forty-one.","Tell her it's forty-one. That's the first thing I've ever checked. It felt very strange."]),
  'corm-idle': n('corm-idle', 'corm', ["I've checked things this week. Real, actual things. It's exhausting.","The bakery's open, and the post runs inside the valley. Both true. Somebody asked.","Bring me anything you hear, and I'll check it. Probably."]),
  'jory-root': n('jory-root', 'jory', ["I have lived at Kettle Springs my whole life, and I have never once been cold.","The warm pool keeps the chill off me. That is the whole reason I stay.","People tell me the pines are not very far away.","I would like to walk as far as the pines, just once. And then come back."], { choices: [c("i could go first.", 'jory-errand', true), c("why the pines?", 'jory-chat')] }),
  'jory-chat': n('jory-chat', 'jory', ["The pines are where the cold starts. Everyone says so.","I have never felt it, and I think I would like to know what it is like.","Or perhaps I would not. I am not sure. Would you go first?"], { next: 'jory-errand' }),
  'jory-errand': n('jory-errand', 'jory', ["Then would you catch me a fish from the warm pool first? It is for the walk, when I go. A mouse should take a lunch.","And then walk to Pinewind Wood for me. Go first, and have a proper look at it.","Then come back and tell me what it is like, and I will decide."]),
  'jory-wait': n('jory-wait', 'jory', ["And then tell me what they are like. All of it, the cold as well."], { fill: 'jory-wait' }),
  'jory-done': n('jory-done', 'jory', ["The pines are like that? Tall, and creaking, and the snow is quiet there?","And it was cold, but you came back. You are standing right here in front of me.","And the fish. I have it wrapped in a leaf, ready for the walk. I have checked it twice.","So I think I can go. Not today, but tomorrow. As far as the pines.","Here, this is for going first. I am not very good at saying thank you."]),
  'jory-idle': n('jory-idle', 'jory', ["This morning I put one foot out of the warm pool. And then both of them.","It was cold. I stood there and counted to forty, and then I got back in.","Tomorrow I will count to fifty. And then the pines. You will see."]),
  'tuck-root': n('tuck-root', 'tuck', ["Careful on the planks, there. I'm Tuck. I look after this bridge.","I tie it, I tighten it, and I check it every hour. I don't cross it, mind. That's a different job.","The rope's wearing out, see? Look at the fraying there. One more storm and it'll snap."], { choices: [c("why don't you cross it?", 'tuck-chat'), c("i've brought you some rope.", 'tuck-rope-seen')] }),
  'tuck-rope-seen': n('tuck-rope-seen', 'tuck', ["Hold on. Is that Bram's good rope? From the woodstore by the big pine?","He sent it all the way up here? With you? He hasn't said a word to me in years."], { next: 'tuck-done' }),
  'tuck-chat': n('tuck-chat', 'tuck', ["Somebody has to stand at this end and watch the knots hold. That's me.","Sable, the fox up at the wind post, says I'm scared. Well, Sable files reports, and I tie knots.","We'll leave it at that."], { next: 'tuck-rope-seen' }),
  'tuck-done': n('tuck-done', 'tuck', ["Forty feet, no splices. He measured it before he gave it to you, didn't he?","There we are. Tied, tightened and tested. That'll hold through a storm.","Tell Bram it's still forty feet, not an inch short. He can come up and measure it himself if he likes.","I didn't cross it, you'll notice. I didn't need to.","And here. I found this tied into the old rope years ago. Show it to Bram. He'll know what it is."]),
  'tuck-chimney': n('tuck-chimney', 'tuck', ["Nettle Chimney can be climbed? The tall rock face past the bridge? You went up it?","Then there's a way up this ridge that doesn't go over a bridge.","I've never said I wouldn't climb, you know. Only that I wouldn't cross.","Tell Sable I'm thinking about it. Only thinking, mind."]),
  'tuck-idle': n('tuck-idle', 'tuck', ["I check this bridge every hour. I don't cross it, though. That's a different job.","The wind's up. The rope doesn't mind the wind. It's age it minds.","Watch the planks on your way over. I mean that kindly."]),
  'sable-root': n('sable-root', 'sable', ["Sable, at the wind post on Windscar Ridge. I measure the wind here and file a report, whatever it says.","So far, today's report just says 'windy'. That won't do at all.","I need two readings, one high and one low. The kite can get me the high one, up over the crest.","And the lantern ascent will get me the low one. I'll read the wind off the flames as you pass them."], { choices: [c("why file it either way?", 'sable-chat'), c("i'll get your readings.", 'sable-errand', true)] }),
  'sable-chat': n('sable-chat', 'sable', ["If I only filed reports on the good days, they wouldn't be reports, would they? They'd be fibs with a stamp on.","Tuck, the marten at the bridge, says the wind will take his bridge one day. I say the rope will go first.","One of us will turn out to be right, and I'll file it either way."], { next: 'sable-errand' }),
  'sable-errand': n('sable-errand', 'sable', ["The kite goes first. Get it up off the crest, above the line of the ridge.","Then run the lantern ascent, gate to gate. I'll watch the flames from here.","Then come back to me, and I'll write it all up."]),
  'sable-wait': n('sable-wait', 'sable', ["The report's still blank, I'm afraid. The kite, above the crest, please.","Then the lantern ascent, up the ridge. Then come back to me."]),
  'sable-done': n('sable-done', 'sable', ["The kite reading's forty, gusting. The lanterns say the same, lower down. That's consistent.","Now that's a report worth filing. I'll stamp it twice.","And for the record, the bridge stood up through all of it. Don't tell Tuck I wrote that down.","Here, this is for the readings."]),
  'sable-b': n('sable-b', 'sable', ["I've got a new question for you. It's been sitting on my desk for a year.","Nettle Chimney is the tall rock face on this ridge. Nobody's ever tried it, and I'd like it on the record.","Take the chimney scramble up to the top. Then go and tell Tuck, the marten at the bridge, that the face can be climbed.","He won't cross a bridge, but he's never said a word about climbing. Then come and tell me."]),
  'sable-bwait': n('sable-bwait', 'sable', ["The chimney still isn't on the record. Take the scramble up to the top.","Then go to Tuck, and then come back to me. I'll file it either way."]),
  'sable-bdone': n('sable-bdone', 'sable', ["It can be climbed, and there's a witness. I'll file that.","And Tuck's thinking about it? Tuck's never thought about anything but knots.","So that's two ways up this ridge now. One for crossers, and one for climbers.","Here, this is for the climb. I'll race you up it next time."]),
  'sable-idle': n('sable-idle', 'sable', ["Forty, gusting. Filed. I file everything.","Somebody keeps lighting the lanterns along the ridge. Good. I like a bit of flicker.","Watch yourself on the crest. The wind doesn't file reports. It just pushes."]),
};
